{
  "charges": [
    {
      "claim": "Regex change incorrectly allows empty label and reduces max length, causing valid 63‑character host labels to not be stripped",
      "file": "__kacheri__/0.test.mjs",
      "line": 208,
      "severity": "major",
      "witnessCode": "import { strict as assert } from 'node:assert';
import normalizeUrl from '../index.js';

const label = 'a'.repeat(63);
const url = `www.${label}.com`;

// Base behavior should strip www. for a 63‑char label
const baseResult = normalizeUrl(url, { stripWWW: true });
assert.ok(!baseResult.startsWith('www.'), 'Base should remove www. for 63‑char label');

// Head behavior fails to strip www. due to the bug
const headResult = normalizeUrl(url, { stripWWW: true });
assert.ok(headResult.startsWith('www.'), 'Head should still have www. due to regression');"
    }
  ]
